package test

import "testing"

// Ported from ui/e2e/cancellation.spec.ts.

func TestE2ECancellationLongRunningCommand(t *testing.T) {
	e2e(t, `Stopping a long-running command shows its cancelled state, also after a reload, and the conversation goes on. "The stop button" is ".status-stop-button"; "the thinking indicator" is [data-testid="agent-thinking"]; "the cancelled tool" is the completed bash tool, .bash-tool[data-testid="tool-call-completed"], containing "sleep 100"; "its Output label" is the cancelled tool's ".bash-tool-label" that contains "Output". "[Operation cancelled]" checks are case-insensitive and scoped to ".messages-container" (the drawer also previews the latest text). Perform the steps in order. 1. Navigate to /c/cancel-command and wait (up to 30s) for the message input (data-testid "message-input") to be visible. 2. Fill the message input with "bash: sleep 100". The send button (data-testid "send-button") should be visible; click it. 3. The thinking indicator should become visible (up to 10s), and a running bash tool (.bash-tool[data-testid="tool-call-running"]) containing "sleep 100" should become visible (up to 10s). 4. The stop button should be visible; click it. 5. The stop button should become hidden (up to 5s), and the thinking indicator hidden (up to 5s). 6. The cancelled tool should become visible (up to 5s). Its ".bash-tool-header" must contain neither "✓" nor "✗" (one assert_text_not_contains on that header for each). 7. Click the cancelled tool's ".bash-tool-header". Its Output label should contain "Output (cancelled):" and must not contain "exit code"; the cancelled tool must have no ".bash-tool-time" (count 0). 8. Inside ".messages-container", an element containing "[Operation cancelled]" should be visible (up to 5s). 9. Reload the page and wait (up to 30s) for the message input to be visible. 10. Once the conversation has loaded, the cancelled tool should be visible, with no ".bash-tool-details" (count 0) until expanded. 11. The thinking indicator should be hidden (within 2s), and the stop button hidden. 12. Click its ".bash-tool-header"; its Output label should contain "Output (cancelled):", and it must have no ".bash-tool-time" (count 0). Inside ".messages-container", an element containing "[Operation cancelled]" should be visible. 13. Fill the message input with "echo: test after cancel" and press Control+Enter in it, as a keyboard does: key_down "Control", press_key "Enter" (the held key applies), key_up "Control" (this sends regardless of the phone's Enter-for-newline behaviour). 14. The first element containing "test after cancel" should be visible (up to 10s). 15. The thinking indicator should be hidden (up to 5s).`, func(s *shelley) {
		s.conversation("echo: cancellation seed", "cancel-command")
	})
}

func TestE2ECancellationTextGeneration(t *testing.T) {
	e2e(t, `Stopping the agent while it is generating text (no tool running) stops it for good. "The stop button" is ".status-stop-button"; "the thinking indicator" is [data-testid="agent-thinking"]. Perform the steps in order. 1. Navigate to /c/cancel-text and wait (up to 30s) for the message input (data-testid "message-input") to be visible. 2. Fill the message input with "delay: 5" and click the send button (data-testid "send-button"). 3. The thinking indicator should become visible (up to 5s). 4. The stop button should be visible; click it. 5. The stop button should become hidden (up to 5s), and the thinking indicator hidden (up to 5s). 6. Reload the page and wait (up to 30s) for the message input to be visible. 7. The thinking indicator should be hidden (within 2s).`, func(s *shelley) {
		s.conversation("echo: cancellation seed", "cancel-text")
	})
}

func TestE2ECancellationWithoutReload(t *testing.T) {
	e2e(t, `After stopping a running command, the page shows the agent idle at once, without a reload, and takes the next message. "The stop button" is ".status-stop-button"; "the thinking indicator" is [data-testid="agent-thinking"]. Perform the steps in order. 1. Navigate to /c/cancel-live and wait (up to 30s) for the message input (data-testid "message-input") to be visible. 2. Fill the message input with "bash: sleep 50" and click the send button (data-testid "send-button"). 3. The thinking indicator should become visible (up to 10s), and a running bash tool (.bash-tool[data-testid="tool-call-running"]) containing "sleep 50" should become visible (up to 10s). 4. Click the stop button. 5. The thinking indicator should become hidden (up to 5s), and the stop button hidden. 6. Fill the message input with "echo: after cancel" and click the send button. 7. The first element containing "after cancel" should become visible (up to 10s).`, func(s *shelley) {
		s.conversation("echo: cancellation seed", "cancel-live")
	})
}
